
from pathlib import Path

import matplotlib
matplotlib.use("Agg")

import matplotlib.pyplot as plt
import pandas as pd

# Paths relative to the repository
ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / "outputs"
DATA = OUT / "AirBnB_all_chch.csv"

OUT.mkdir(parents=True, exist_ok=True)

# Load the Christchurch data generated by Marian's script
df = pd.read_csv(DATA)

df["year_month"] = pd.to_datetime(
    df["year_month"].astype(str),
    format="%Y-%m",
    errors="coerce"
)

df["price"] = pd.to_numeric(df["price"], errors="coerce")
df["number_of_reviews"] = pd.to_numeric(
    df["number_of_reviews"], errors="coerce"
)
df["last_review"] = pd.to_datetime(
    df["last_review"], errors="coerce"
)

if df["year_month"].notna().sum() == 0:
    raise ValueError("No valid year_month values found.")

latest_month = df["year_month"].max()
latest = df.loc[df["year_month"] == latest_month].copy()

if latest.empty:
    raise ValueError("No listings found for latest month.")

month_label = latest_month.strftime("%B %Y")

# --------------------------------------------------
# 1. SUMMARY STATISTICS
# --------------------------------------------------

df.describe(include="all").to_csv(
    OUT / "leland_summary_statistics.csv"
)

df.corr(numeric_only=True).to_csv(
    OUT / "leland_correlations.csv"
)

missingness = pd.DataFrame({
    "missing_count": df.isna().sum(),
    "missing_percentage": df.isna().mean() * 100
})

missingness.to_csv(OUT / "leland_missingness.csv")

missing_corr = df.isna().astype(int).corr()
missing_corr = missing_corr.dropna(axis=0, how="all")
missing_corr = missing_corr.dropna(axis=1, how="all")
missing_corr.to_csv(OUT / "leland_missingness_correlations.csv")

# Boxplots for meaningful numeric columns
exclude = {"id", "host_id", "latitude", "longitude", "license"}

numeric_cols = [
    c for c in df.select_dtypes(include="number").columns
    if c not in exclude
]

for col in numeric_cols:
    values = df[col].dropna()
    if values.empty:
        continue

    fig, ax = plt.subplots(figsize=(8, 4))
    ax.boxplot(values)
    ax.set_title(f"Boxplot of {col}")
    ax.set_ylabel(col)

    fig.savefig(
        OUT / f"leland_boxplot_{col}.png",
        dpi=200,
        bbox_inches="tight"
    )
    plt.close(fig)

# --------------------------------------------------
# 2. PRICE HISTOGRAMS
# --------------------------------------------------

for data, filename, title in [
    (df, "leland_price_all.png", "All available months"),
    (latest, "leland_price_latest.png", month_label),
]:
    values = data["price"].dropna()

    if values.empty:
        raise ValueError(f"No valid prices for {title}")

    fig, ax = plt.subplots(figsize=(10, 6))
    ax.hist(values, bins=50, edgecolor="black")
    ax.set_title(f"Christchurch Airbnb prices — {title}")
    ax.set_xlabel("Price")
    ax.set_ylabel("Number of listings")

    fig.savefig(OUT / filename, dpi=200, bbox_inches="tight")
    plt.close(fig)

# --------------------------------------------------
# 3. DAYS SINCE LAST REVIEW
# --------------------------------------------------

# Preserve the original notebook's calculation:
# each month's latest observed review is the reference date.
reference_dates = df.groupby("year_month")["last_review"].transform("max")

df["days_since_review"] = (
    reference_dates - df["last_review"]
).dt.days

latest_reviews = df.loc[
    df["year_month"] == latest_month,
    "days_since_review"
].dropna()

if latest_reviews.empty:
    raise ValueError(f"No valid review dates for {month_label}")

fig, ax = plt.subplots(figsize=(10, 6))
ax.hist(latest_reviews, bins=50, edgecolor="black")
ax.set_title(f"Days since last review — {month_label}")
ax.set_xlabel("Days since last review")
ax.set_ylabel("Number of listings")

fig.savefig(
    OUT / "leland_days_since_review.png",
    dpi=200,
    bbox_inches="tight"
)
plt.close(fig)

# --------------------------------------------------
# 4. TOP 10% MOST REVIEWED LISTINGS
# --------------------------------------------------

reviews = latest["number_of_reviews"].dropna()

if reviews.empty:
    raise ValueError(f"No review counts for {month_label}")

cutoff = reviews.quantile(0.90)

top = latest.loc[
    latest["number_of_reviews"] >= cutoff
]

counts = top["neighbourhood"].value_counts()

if counts.empty:
    raise ValueError("No neighbourhood data for top-reviewed listings.")

fig, ax = plt.subplots(figsize=(10, 6))
counts.sort_values().plot(kind="barh", ax=ax)

ax.set_title(
    f"Top 10% most reviewed listings by neighbourhood — {month_label}"
)
ax.set_xlabel("Number of listings")
ax.set_ylabel("Neighbourhood")

fig.savefig(
    OUT / "leland_top10_reviews.png",
    dpi=200,
    bbox_inches="tight"
)
plt.close(fig)

# Completion marker for Make
(OUT / "leland_reports.done").write_text(
    f"Reports generated for {month_label}\n"
)

print(f"Successfully generated Leland's reports for {month_label}")
